<script setup lang="ts">import type{ApiSuccess}from'~/types/api';useHead({title:'Logiciels gratuits'});type Software={id:string;slug:string;name:string;description:string|null;audience:string|null;platforms:string[];license:string|null;openSource:boolean;repoUrl:string|null;docsUrl:string|null;videoUrl:string|null;status:string;category:{id:string;name:string;kind:string}|null;latestVersion:{version:string;downloadUrl:string|null;sha256:string|null;fileSize:string|null;publishedAt:string|null}|null;downloadCount:number};const{data}=await useFetch<ApiSuccess<Software[]>>('/api/public/software');const items=computed(()=>data.value?.data??[])</script>
<template><section class="section"><div class="container"><p class="eyebrow">Logiciels & outils gratuits</p><h1 class="display-title">Des outils accessibles, documentés et publiés avec prudence.</h1><p class="lead">Le catalogue distingue les logiciels réalisés par IFICS des ressources tierces recommandées. Une publication indique sa version, sa licence et, lorsqu’un fichier est hébergé, son empreinte SHA-256.</p><div v-if="items.length" class="grid grid-3 software-grid"><article v-for="item in items" :key="item.id" class="card card-pad"><div class="actions"><span class="badge">{{item.status}}</span><span v-if="item.category" class="badge badge-muted">{{item.category.name}}</span></div><h2>{{item.name}}</h2><p>{{item.description}}</p><p class="muted">{{item.platforms.join(' · ')}} · {{item.license||'Licence non renseignée'}}</p><p v-if="item.latestVersion"><strong>Version {{item.latestVersion.version}}</strong><br><code v-if="item.latestVersion.sha256">SHA-256 : {{item.latestVersion.sha256}}</code></p><div class="actions"><a v-if="item.latestVersion?.downloadUrl" :href="item.latestVersion.downloadUrl" class="btn btn-primary">Télécharger</a><a v-if="item.repoUrl" :href="item.repoUrl" class="btn btn-secondary">Code source</a><a v-if="item.docsUrl" :href="item.docsUrl" class="btn btn-secondary">Documentation</a></div></article></div><div v-else class="empty-state">Le catalogue public sera alimenté après validation technique des premières ressources.</div></div></section></template>
<style scoped>.software-grid{margin-top:35px}.software-grid h2{font-size:1.3rem}.software-grid p{color:var(--ifics-muted)}code{font-size:.7rem;word-break:break-all;color:#4c5d54}</style>
